"""OCR helpers for the invoice-processing module."""
import re

import pytesseract
from PIL import Image

TOTAL_PATTERN = re.compile(r"(?:total|amount due)[:\s]*\$?([\d,]+\.\d{2})", re.IGNORECASE)


def parse_total(text):
    match = TOTAL_PATTERN.search(text)
    if not match:
        return None
    return float(match.group(1).replace(",", ""))


def parse_currency_totals(text, currencies):
    results = {}
    for code in currencies:
        pattern = re.compile(rf"{code}[:\s]*\$?([\d,]+\.\d{{2}})", re.IGNORECASE)
        match = pattern.search(text)
        if match:
            results[code] = float(match.group(1).replace(",", ""))
    return results


def extract_text(image_path):
    image = Image.open(image_path)
    return pytesseract.image_to_string(image)


def extract_totals(image_path):
    return parse_total(extract_text(image_path))


def extract_currency_totals(image_path, currencies):
    return parse_currency_totals(extract_text(image_path), currencies)

